function isValidIsbn10(text) {
  // A non-string throws a TypeError
  if (typeof text !== 'string') {
    throw new TypeError('ISBN must be a string');
  }

  // Remove hyphens and spaces
  const cleaned = text.replace(/[-\s]/g, '');

  // Must be exactly 10 characters
  if (cleaned.length !== 10) {
    return false;
  }

  // First 9 must be digits, last must be digit or X
  const pattern = /^\d{9}[0-9X]$/i;
  if (!pattern.test(cleaned)) {
    return false;
  }

  // Calculate weighted sum: positions 0-8 get weights 10-2, position 9 gets weight 1
  let sum = 0;
  for (let i = 0; i < 9; i++) {
    sum += parseInt(cleaned[i], 10) * (10 - i);
  }

  // Handle check character: X is 10, digit is its numeric value
  const checkChar = cleaned[9].toUpperCase();
  const checkValue = checkChar === 'X' ? 10 : parseInt(checkChar, 10);
  sum += checkValue * 1;

  // Valid if sum is divisible by 11
  return sum % 11 === 0;
}

module.exports = { isValidIsbn10 };
